<?php load_view('partials/booking_passports',['booking'=>$booking,'billing'=>$billing,'passport_admin'=>false]); ?>
<section class="panel"><h2>ประวัติการดำเนินการ</h2><ol class="booking-timeline"><?php foreach ($s['events'] as $event): ?><li><small><?= e($event['created_at']) ?></small><p><?= e($event['message']) ?></p></li><?php endforeach ?><li><small><?= e($booking['created_at']) ?></small><p>ได้รับคำขอจอง</p></li></ol></section></div>
