<?php if ($booking['status']==='cancelled'): ?><p class="notice">การจองถูกยกเลิกแล้ว<?php if ($s['paid']>0): ?> · มียอดรับเงิน กรุณาติดต่อทีมงานเพื่อตรวจสอบการคืนเงิน<?php endif ?></p>
<?php elseif ($booking['status']==='confirmed' && $s['invoice']): ?>
