<?php elseif ($booking['status']==='confirmed'): ?><p>ยืนยันการจองแล้ว ทีมงานกำลังเตรียม Invoice เพื่อเปิดรับชำระเงิน</p><?php else: ?><p>ทีมงานกำลังตรวจสอบรายละเอียด ยังไม่ยืนยันบริการและยังไม่เปิดชำระเงิน</p><?php endif ?>
